		var y = col_r + 100;
		var y1 = 255 < y ? 255 : y;
		var c_r = (0 > y1 ? 0 : y1) | 0;
		var y = col_g + 100;
		var y1 = 255 < y ? 255 : y;
		var c_g = (0 > y1 ? 0 : y1) | 0;
		var y = col_b + 100;
		var y1 = 255 < y ? 255 : y;
		var c_b = (0 > y1 ? 0 : y1) | 0;
		light = c_r << 16 | c_g << 8 | c_b;
